#include <iostream>
using namespace std;

int main() {
    int day = 6;              // 6 = Saturday, 7 = Sunday
    bool onHoliday = false;

    bool weekend = day == 6 || day == 7;
    bool dayOff = weekend || onHoliday;
    bool working = !dayOff;

    cout << boolalpha;
    cout << "Weekend: " << weekend << endl;
    cout << "Day off: " << dayOff << endl;
    cout << "Working: " << working << endl;
    return 0;
}

