#include <iostream>
using namespace std;

int main() {
    int people;
    int bill;

    cout << "How many people? ";
    cin >> people;

    cout << "Total bill? ";
    cin >> bill;

    // If people is 0, the division on the right is never run.
    bool affordable = people > 0 && bill / people <= 500;

    cout << boolalpha;
    cout << "Affordable each: " << affordable << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int marks;
    int attendance;

    cout << "Marks out of 100? ";
    cin >> marks;

    cout << "Attendance percent? ";
    cin >> attendance;

    bool passedMarks = marks >= 40;
    bool goodAttendance = attendance >= 75;
    bool distinction = marks >= 75 && goodAttendance;

    cout << boolalpha;
    cout << "Passed marks:     " << passedMarks << endl;
    cout << "Good attendance:  " << goodAttendance << endl;
    cout << "Gets certificate: " << (passedMarks && goodAttendance) << endl;
    cout << "With distinction: " << distinction << endl;
    return 0;
}

